const recoveryEntry=(()=>{const url=new URL(location.href),fragment=new URLSearchParams(url.hash.slice(1)),callback=configured&&(fragment.get('type')==='recovery'||url.searchParams.get('view')==='recovery'||['error','error_code','error_description'].some(key=>fragment.has(key)||url.searchParams.has(key)));const hash=callback?url.hash:'';if(callback){url.hash='';for(const key of ['view','error','error_code','error_description','type','access_token','refresh_token','expires_in','expires_at','token_type'])url.searchParams.delete(key);history.replaceState({},'',url);}return {callback,hash};})();
const recoveryCallback=recoveryEntry.callback;
let service=configured?api:demo,actor=null,route='login',draft=null,detail=null,pending=false,loadSequence=0,toastTimer,activeReport=null,editingUser=null,userRecords=[],remoteNotifications=[];
if(!configured){const demoRows=rows=>{for(const row of rows||[]){if(row.po_number==='DEMO-2026-00005'){for(const item of row.items||[]){if(item.vat&&item.unit_price==='214'){Object.assign(item,validateItems([{...item,unit_price:'200'}])[0]);} }Object.assign(row,totals(row.items));}}return rows;};const demoList=service.list.bind(service),demoDetail=service.detail.bind(service),demoReport=service.report.bind(service);service.list=async(...args)=>{const result=await demoList(...args);demoRows(result.rows);return result;};service.detail=async id=>demoRows([await demoDetail(id)])[0];service.report=async month=>{const result=await demoReport(month);demoRows(result.rows);Object.assign(result,summarizeMonth(result.rows));return result;};}
if(!configured){const seedList=service.list.bind(service),seedStats=service.stats.bind(service),seedDetail=service.detail.bind(service),seedReport=service.report.bind(service),seedCreate=service.create.bind(service),seedRowsPromise=seedList('',1).then(result=>result.rows.filter(row=>row.created_by==='demo-office')),resetKey='po-the-grands-demo-po-reset-20260928-v1';if(!localStorage.getItem(resetKey)){localStorage.removeItem('po-the-grands-notifications-v1');localStorage.setItem(resetKey,'done');}service.list=async(status,page=1)=>{const seeds=await seedRowsPromise,hidden=new Set(seeds.map(row=>row.id)),result=await seedList(status,page),removed=seeds.filter(row=>!status||row.status===status).length;return {...result,rows:result.rows.filter(row=>!hidden.has(row.id)),total:Math.max(0,result.total-removed)};};service.stats=async()=>{const seeds=await seedRowsPromise,result={...await seedStats()};for(const row of seeds)result[row.status]=Math.max(0,(result[row.status]||0)-1);return result;};service.detail=async id=>{const seeds=await seedRowsPromise;if(seeds.some(row=>row.id===id))throw Error('ไม่พบใบ PO');return seedDetail(id);};service.report=async month=>{const seeds=await seedRowsPromise,hidden=new Set(seeds.map(row=>row.id)),result=await seedReport(month),rows=(result.rows||[]).filter(row=>!hidden.has(row.id));return {...result,...summarizeMonth(rows),rows};};let newDemoNumber=(()=>{try{return JSON.parse(localStorage.getItem('po-the-grands-demo-orders-v1')||'[]').length+1}catch{return 1}})();service.create=async(...args)=>{const result=await seedCreate(...args);result.po_number=`DEMO-${new Date().getFullYear()}-${String(newDemoNumber++).padStart(5,'0')}`;try{const stored=JSON.parse(localStorage.getItem('po-the-grands-demo-orders-v1')||'[]'),row=stored.find(item=>item.id===result.id);if(row){row.po_number=result.po_number;localStorage.setItem('po-the-grands-demo-orders-v1',JSON.stringify(stored));}}catch{}return result;};}
if(!configured){const unscopedList=service.list.bind(service);async function demoScopedRows(status){const first=await unscopedList(status,1),rows=[...first.rows];for(let page=2;page<=Math.ceil(first.total/10);page++)rows.push(...(await unscopedList(status,page)).rows);return rows;}service.list=async(status,page=1,scope='all')=>{let rows=await demoScopedRows(status);if(actor?.role==='office'&&(!actor.can_export_report||scope==='mine'))rows=rows.filter(row=>row.created_by===actor.id);return {rows:rows.slice((page-1)*10,page*10),total:rows.length};};service.stats=async(scope='all')=>{let rows=await demoScopedRows('');if(actor?.role==='office'&&(!actor.can_export_report||scope==='mine'))rows=rows.filter(row=>row.created_by===actor.id);return Object.fromEntries(Object.keys(statuses).map(status=>[status,rows.filter(row=>row.status===status).length]));};}
const createWithNotification=service.create.bind(service);service.create=async(...args)=>{const result=await createWithNotification(...args);addWorkflowNotification(result,'create',actor);return result;};
const actionWithNotification=service.action.bind(service);service.action=async(...args)=>{const result=await actionWithNotification(...args);addWorkflowNotification(result,args[1],actor);return result;};
if(configured){const saveOffice=service.saveOffice.bind(service);service.saveOffice=account=>saveOffice({...account,profile_id:editingUser?.id||null});}
if(!configured){const saveOffice=service.saveOffice.bind(service);service.saveOffice=async(account,owner)=>{const requested=String(account.username||'').trim().toLowerCase(),existing=editingUser;const result=await saveOffice({...account,username:existing?.username||requested,id:existing?.id||null},owner);if(existing&&requested!==existing.username){const accounts=JSON.parse(localStorage.getItem('po-the-grands-demo-accounts-v1')||'[]'),saved=accounts.find(a=>a.id===existing.id);if(saved){saved.username=requested;localStorage.setItem('po-the-grands-demo-accounts-v1',JSON.stringify(accounts));result.username=requested;}}return result;};}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({department:'',name:'',spec:'',source:'',note:'',qty:'1',unit:'',unit_price:'',vat:false,payment_method:''});
const defaultDepartments=['อาหาร','ของหวาน','ผลไม้','ติ่มซำ','แซนวิช','สลัด','ครัวกลาง','แม่บ้าน','ออฟฟิศ','ช่าง','ภูดอย','บ้านโจ้','ท่ารั้ว'];
let currentDepartments=defaultDepartments;
const departments=()=>service.departments?service.departments():Promise.resolve(defaultDepartments);
const field=(id,label,value='',type='text',attrs='')=>{const required=label.endsWith(' *'),text=required?label.slice(0,-2):label;return `<div class="field"><label for="${id}">${text}${required?' <span class="required-mark">*</span>':''}</label><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}><span id="${id}-error" class="field-error"></span></div>`;};
const badge=s=>`<span class="badge ${s}">${statuses[s]}</span>`;
function timeOnly(s){return new Intl.DateTimeFormat('th-TH',{timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(s));}
function shortPoDate(s){return new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}).format(new Date(`${s}T12:00:00+07:00`));}
function tracker(p,large=false){const done={pending:0,approved:1,received:2,closed:3,rejected:0}[p.status];return `<ol class="tracker status-${p.status} ${large?'large':''}" aria-label="ขั้นตอนใบ PO">${['เปิด PO','อนุมัติ','รับสินค้า','ปิด PO'].map((s,n)=>`<li class="${n<=done?'done':n===done+1&&p.status!=='rejected'?'current':''}" ${n===done+1&&p.status!=='rejected'?'aria-current="step"':''}>${s}${n<=done?'<span class="sr-only"> เสร็จแล้ว</span>':''}</li>`).join('')}</ol>`;}
function notify(text){clearTimeout(toastTimer);document.querySelector('#toast').textContent=text;toastTimer=setTimeout(()=>document.querySelector('#toast').textContent='',5000);}
const notificationKey='po-the-grands-notifications-v1';
function allNotifications(){try{return JSON.parse(localStorage.getItem(notificationKey)||'[]')}catch{return []}}
function myNotifications(){return configured?remoteNotifications:allNotifications().filter(n=>actor&&(actor.role==='owner'?n.recipient_role==='owner':n.recipient_id===actor.id));}
function addWorkflowNotification(po,action,sourceActor){const copy={create:['มีใบขอซื้อใหม่',`${sourceActor.display_name} เปิด ${po.po_number}`],approve:['ใบขอซื้อได้รับอนุมัติ',`${po.po_number} ได้รับอนุมัติแล้ว`],reject:['ใบขอซื้อไม่อนุมัติ',`${po.po_number} ไม่ได้รับอนุมัติ`],receive:['ได้รับสินค้าแล้ว',`${sourceActor.display_name} ยืนยันรับสินค้า ${po.po_number}`],close:['ปิดใบ PO แล้ว',`${po.po_number} ตรวจรับเอกสารและปิดแล้ว`]}[action];if(!copy)return;const rows=allNotifications(),event_key=`${po.id}:${action}:${po.version||1}`;if(rows.some(n=>n.event_key===event_key))return;rows.unshift({id:crypto.randomUUID(),event_key,po_id:po.id,recipient_role:['create','receive'].includes(action)?'owner':'office',recipient_id:['create','receive'].includes(action)?null:po.created_by,title:copy[0],message:copy[1],action,created_at:new Date().toISOString(),read_at:null});localStorage.setItem(notificationKey,JSON.stringify(rows.slice(0,100)));}
function notificationButton(){const unread=myNotifications().filter(n=>!n.read_at).length;return `<button type="button" class="notification-button" data-action="notifications" aria-label="การแจ้งเตือน${unread?`ที่ยังไม่ได้อ่าน ${unread} รายการ`:''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${unread?`<span>${unread}</span>`:''}</button>`;}
async function refreshNotifications(){if(!configured||!actor)return;try{remoteNotifications=await service.notifications();const old=document.querySelector('.notification-button');if(old)old.outerHTML=notificationButton();}catch{}}
async function openNotifications(){const rows=myNotifications();openModal('การแจ้งเตือน',`<div class="notification-list">${rows.map(n=>`<button type="button" class="notification-item ${n.read_at?'':'unread'}" data-notification-po="${n.po_id}"><strong>${esc(n.title)}</strong><span>${esc(n.message)}</span><small>${date(n.created_at)}</small></button>`).join('')||'<div class="empty"><p>ยังไม่มีการแจ้งเตือน</p></div>'}</div><div class="actions"><button type="button" data-cancel>ปิด</button></div>`);if(configured){await service.markNotificationsRead();remoteNotifications=rows.map(n=>({...n,read_at:n.read_at||new Date().toISOString()}));}else{const all=allNotifications(),ids=new Set(rows.map(n=>n.id)),now=new Date().toISOString();for(const n of all)if(ids.has(n.id)&&!n.read_at)n.read_at=now;localStorage.setItem(notificationKey,JSON.stringify(all));}document.querySelector('.notification-button span')?.remove();}
function navButton(go,label){return `<button data-go="${go}" class="${route===go?'selected':''}">${label}</button>`;}
function shell(body){window.scrollTo(0,0);app.innerHTML=`<div class="shell route-${route}"><aside class="sidebar"><div><div class="logo"><img src="favicon.svg?v=20260927-3" alt="">PO The Grands</div><div class="side-caption">PURCHASE ORDER WORKSPACE</div></div><nav class="nav" aria-label="เมนูหลัก">${navButton('list','▤ &nbsp; ใบขอซื้อทั้งหมด')}${actor.role==='office'?navButton('create','＋ &nbsp; เปิดใบ PO'):''}${actor.role==='office'?navButton('departments','▥ &nbsp; แผนก/สาขา'):''}${actor.role==='office'?navButton('report','▦ &nbsp; สรุปรายเดือน'):''}${actor.role==='owner'?navButton('users','♙ &nbsp; ผู้ใช้งาน'):''}${configured&&actor.role==='owner'?navButton('account','⚙ &nbsp; บัญชีของฉัน'):''}</nav></aside><main class="main"><header class="topbar"><span>พื้นที่ทำงาน / ใบขอซื้อ</span><div class="identity"><span class="avatar" aria-hidden="true">${actor.role==='owner'?'♛':'♙'}</span><strong>${esc(actor.display_name)}</strong><button data-action="logout" class="ghost">เปลี่ยนบัญชีผู้ใช้งาน</button></div></header><div class="content">${!configured?'<div class="demo-banner"><span><strong>ระบบทดลอง</strong> · ข้อมูล PO จะเริ่มใหม่เมื่อรีโหลดหน้า ส่วนบัญชีทดลองเก็บเฉพาะเครื่องนี้</span><button data-go="setup">ดูการเชื่อมต่อ</button></div>':''}${body}</div></main></div>`;document.title=({list:'ใบขอซื้อ',create:'เปิดใบ PO',review:'ตรวจทานใบ PO',detail:detail?.po_number||'รายละเอียด',report:'สรุปรายเดือน',users:'ผู้ใช้งาน',account:'บัญชีของฉัน',setup:'การเชื่อมต่อ'}[route]||'เข้าสู่ระบบ')+' — PO The Grands';}
function showError(e,target=document.querySelector('#page-error')){if(target){target.innerHTML=`<div class="error" role="alert">${esc(e.message||e)}${e.authExpired?' <button data-action="reauth">เข้าสู่ระบบอีกครั้ง</button>':''}</div>`;target.scrollIntoView({block:'nearest'});}else notify(e.message||String(e));}
function openModal(title,body,onSubmit){const prev=document.activeElement;modal.innerHTML=`<h2 id="modal-title">${title}</h2>${body}`;modal.showModal();modal.querySelector('[data-cancel]')?.addEventListener('click',()=>modal.close());modal.onclose=()=>{if(prev?.isConnected)prev.focus();};modal.oncancel=e=>{if(pending)e.preventDefault();};const form=modal.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();if(!pending)await onSubmit(new FormData(form));};}
function errorField(input,message){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',input.id+'-error');document.getElementById(input.id+'-error').textContent=message;input.focus();}
async function withPending(button,task,errorTarget){if(pending)return;pending=true;const buttons=[...document.querySelectorAll('button')],states=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);button?.setAttribute('aria-busy','true');try{await task();}catch(e){showError(e,errorTarget||document.querySelector('#page-error'));}finally{pending=false;buttons.forEach((b,i)=>{if(b.isConnected)b.disabled=states[i];});button?.removeAttribute('aria-busy');}}
function passwordControl(id,label,autocomplete='current-password',value=''){return `<div class="field"><label for="${id}">${label}</label><div class="password-wrap"><input id="${id}" name="${id}" type="password" autocomplete="${autocomplete}" value="${esc(value)}"><button type="button" class="password-toggle" data-reveal="${id}" aria-label="แสดง${label}" aria-pressed="false"><svg class="eye-icon eye-open" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.8"/></svg><svg class="eye-icon eye-closed" viewBox="0 0 24 24" aria-hidden="true"><path d="m3 3 18 18M10.6 5.9A10.8 10.8 0 0 1 12 5.8c6.5 0 10 6.2 10 6.2a19 19 0 0 1-3.4 3.9M6.3 6.3C3.5 8.1 2 12 2 12s3.5 6 10 6c1.4 0 2.7-.3 3.8-.7"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div><span class="field-error" id="${id}-error"></span></div>`;}
function bindPasswordToggles(){document.querySelectorAll('[data-reveal]').forEach(button=>button.onclick=()=>{const input=document.getElementById(button.dataset.reveal),show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-label',(show?'ซ่อน':'แสดง')+'รหัสผ่าน');button.setAttribute('aria-pressed',String(show));button.classList.toggle('is-visible',show);});}
function renderOwnerSetup(){route='login';app.innerHTML=`<main class="login"><div class="logo"><img src="favicon.svg?v=20260927-3" alt="">PO The Grands</div><section class="panel"><div class="eyebrow">FIRST TIME SETUP</div><h1>ตั้งค่าบัญชีเจ้าของ</h1><p class="muted">กำหนดรหัสผ่านเจ้าของก่อนเริ่มใช้งานระบบทดลอง จากนั้นเจ้าของจะตั้งบัญชีออฟฟิศได้</p><form id="owner-setup" novalidate><div id="page-error"></div>${passwordControl('password','รหัสผ่านเจ้าของ','new-password')}${passwordControl('confirm','ยืนยันรหัสผ่าน','new-password')}<button type="submit" class="primary wide">บันทึกและเข้าสู่ระบบ</button></form></section></main>`;document.title='ตั้งค่าบัญชีเจ้าของ — PO The Grands';bindPasswordToggles();document.querySelector('#owner-setup').onsubmit=async e=>{e.preventDefault();const pass=document.querySelector('#password'),confirm=document.querySelector('#confirm');if(pass.value.length<6){errorField(pass,'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');return;}if(pass.value!==confirm.value){errorField(confirm,'รหัสผ่านทั้งสองช่องไม่ตรงกัน');return;}await withPending(e.submitter,async()=>{actor=await demoAuth.setupOwner(pass.value);await renderList();notify('ตั้งค่าบัญชีเจ้าของแล้ว');});};}
function resetOwner(){route='login';app.innerHTML=`<main class="login"><div class="logo"><img src="favicon.svg?v=20260927-3" alt="">PO The Grands</div><section class="panel"><div class="eyebrow">DEMO RECOVERY</div><h1>ตั้งรหัสเจ้าของใหม่</h1><p class="muted">ใช้สำหรับโหมดทดลองในเครื่องนี้เท่านั้น ไม่เกี่ยวกับ Supabase และไม่ลบรายการตัวอย่าง</p><form id="owner-reset" novalidate><div id="page-error"></div>${passwordControl('password','รหัสผ่านใหม่','new-password')}${passwordControl('confirm','ยืนยันรหัสผ่าน','new-password')}<button type="submit" class="primary wide">บันทึกรหัสใหม่</button><button type="button" class="wide" data-action="back-login">กลับหน้า Login</button></form></section></main>`;document.title='ตั้งรหัสเจ้าของใหม่ — PO The Grands';bindPasswordToggles();document.querySelector('#owner-reset').onsubmit=async e=>{e.preventDefault();const pass=document.querySelector('#password'),confirm=document.querySelector('#confirm');if(pass.value.length<6){errorField(pass,'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');return;}if(pass.value!==confirm.value){errorField(confirm,'รหัสผ่านทั้งสองช่องไม่ตรงกัน');return;}await withPending(e.submitter,async()=>{await demoAuth.resetOwner(pass.value);notify('ตั้งรหัสเจ้าของใหม่แล้ว');login();});};}
function recoveryShell(body){route='recovery';actor=null;app.innerHTML=`<main class="login"><div class="logo"><img src="favicon.svg?v=20260927-3" alt="">PO The Grands</div><section class="panel">${body}</section></main>`;document.title='กู้รหัสผ่านเจ้าของ — PO The Grands';}
function requestOwnerRecovery(){
 if(!configured)return;api.cancelOwnerRecovery();
 recoveryShell(`<h1>ลืมรหัสผ่านเจ้าของ</h1><p class="muted">กรอกชื่อเข้าระบบหรืออีเมลเจ้าของ ระบบจะส่งลิงก์ตั้งรหัสใหม่ไปยังอีเมลเดิมที่ผูกกับบัญชี</p><form id="owner-recovery-request-form" novalidate><div id="page-error"></div>${field('recovery-username','ชื่อเข้าระบบหรืออีเมลเจ้าของ','','text','autocomplete="username"')}<button type="submit" class="primary wide">ส่งลิงก์ตั้งรหัสผ่านใหม่</button></form><p class="form-note">บัญชีพนักงานออฟฟิศ ให้ติดต่อเจ้าของเพื่อเปลี่ยนรหัสผ่าน</p><button type="button" class="ghost wide" data-action="owner-recovery-cancel">กลับเข้าสู่ระบบ</button>`);
 document.querySelector('#owner-recovery-request-form').onsubmit=async e=>{e.preventDefault();const username=document.querySelector('#recovery-username');if(!username.value.trim())return errorField(username,'กรอกชื่อเข้าระบบหรืออีเมลเจ้าของ');await withPending(e.submitter,async()=>{await api.requestOwnerRecovery(username.value.trim());recoveryShell('<h1>ตรวจอีเมลของคุณ</h1><p role="status">หากข้อมูลตรงกับบัญชีเจ้าของ ระบบจะส่งลิงก์ตั้งรหัสผ่านใหม่ไปยังอีเมลที่ผูกไว้ กรุณาตรวจกล่องจดหมายและโฟลเดอร์สแปม</p><button type="button" class="ghost wide" data-action="owner-recovery-request">ขอลิงก์ใหม่</button><button type="button" class="primary wide" data-action="owner-recovery-cancel">กลับเข้าสู่ระบบ</button>');});};
}
function invalidOwnerRecovery(){api.cancelOwnerRecovery();recoveryShell('<h1>ลิงก์ตั้งรหัสผ่านใช้ไม่ได้</h1><p class="error" role="alert">ลิงก์ไม่ถูกต้องหรือหมดอายุแล้ว กรุณาขอลิงก์ใหม่และเปิดอีเมลล่าสุด</p><button type="button" class="primary wide" data-action="owner-recovery-request">ขอลิงก์ใหม่</button><button type="button" class="ghost wide" data-action="owner-recovery-cancel">กลับเข้าสู่ระบบ</button>');}
function resetOwnerRecovery(){
 recoveryShell(`<h1>ตั้งรหัสผ่านเจ้าของใหม่</h1><p class="muted">ตั้งรหัสผ่านใหม่สำหรับบัญชีเจ้าของ แล้วเข้าสู่ระบบอีกครั้ง</p><form id="owner-recovery-reset-form" novalidate><div id="page-error"></div>${passwordControl('recovery-new-password','รหัสผ่านใหม่','new-password')}${passwordControl('recovery-confirm-password','ยืนยันรหัสผ่านใหม่','new-password')}<p class="form-note">รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร</p><button type="submit" class="primary wide">บันทึกรหัสผ่านใหม่</button></form><button type="button" class="ghost wide" data-action="owner-recovery-cancel">ยกเลิกและกลับเข้าสู่ระบบ</button>`);bindPasswordToggles();
 document.querySelector('#owner-recovery-reset-form').onsubmit=async e=>{e.preventDefault();const password=document.querySelector('#recovery-new-password'),confirm=document.querySelector('#recovery-confirm-password');if(password.value.length<6)return errorField(password,'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');if(password.value!==confirm.value)return errorField(confirm,'รหัสผ่านทั้งสองช่องไม่ตรงกัน');await withPending(e.submitter,async()=>{await api.resetOwnerRecovery(password.value);password.value='';confirm.value='';api.cancelOwnerRecovery();login();notify('บันทึกรหัสผ่านใหม่แล้ว กรุณาเข้าสู่ระบบด้วยรหัสใหม่');});};
}
async function beginOwnerRecovery(){recoveryShell('<h1>กำลังตรวจสอบลิงก์</h1><p role="status">กำลังตรวจสอบลิงก์ตั้งรหัสผ่านใหม่…</p>');try{const validation=api.beginOwnerRecovery(recoveryEntry.hash);recoveryEntry.hash='';if(await validation)resetOwnerRecovery();else invalidOwnerRecovery();}catch{recoveryEntry.hash='';invalidOwnerRecovery();}}
function login(reauth=false){route='login';++loadSequence;app.innerHTML=`<main class="login"><div class="logo"><img src="favicon.svg?v=20260927-3" alt="">PO The Grands</div><section class="panel"><div class="eyebrow">SECURE ACCESS</div><h1>เข้าสู่ระบบ</h1><p class="muted">ใช้งานด้วยบัญชีที่เจ้าของกำหนดให้</p><form id="login-form" novalidate><div id="page-error"></div>${field('username',configured?'ชื่อผู้ใช้ หรืออีเมลเจ้าของ':'ชื่อผู้ใช้','','text','autocomplete="username"')}${passwordControl('password','รหัสผ่าน')}<button type="submit" class="primary wide">เข้าสู่ระบบ</button></form>${configured?'<button type="button" class="ghost wide" data-action="owner-recovery-request">ลืมรหัสผ่านเจ้าของ?</button>':''}${!configured?'<p class="form-note">ครั้งแรกให้เจ้าของเข้าสู่ระบบ แล้วเปิดเมนู “ผู้ใช้งาน” เพื่อกำหนดบัญชีและรหัสผ่านให้ออฟฟิศ</p><button type="button" class="ghost wide" data-action="reset-owner">ลืมรหัสเจ้าของ? ตั้งใหม่ในโหมดทดลอง</button>':''}</section></main>`;document.title='เข้าสู่ระบบ — PO The Grands';bindPasswordToggles();document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const username=document.querySelector('#username'),password=document.querySelector('#password');if(!username.value.trim()){errorField(username,configured?'กรอกชื่อผู้ใช้ หรืออีเมลเจ้าของ':'กรอกชื่อผู้ใช้');return;}if(!password.value){errorField(password,'กรอกรหัสผ่าน');return;}await withPending(e.submitter,async()=>{const oldId=actor?.id,next=configured?await api.login(username.value.trim(),password.value):await demoAuth.login(username.value,password.value);actor=next;if(reauth&&oldId!==next.id)draft=null;if(reauth&&draft&&next.role==='office')renderCreate();else await renderList();});};}
function getFilter(){const s=new URLSearchParams(location.search).get('status')||'';return s in statuses?s:'';}
function getPage(){return Math.max(1,Math.floor(Number(new URLSearchParams(location.search).get('page'))||1));}
function getScope(){if(actor?.role!=='office')return'all';if(!actor.can_export_report)return'mine';return new URLSearchParams(location.search).get('scope')==='mine'?'mine':'all';}
function setListState(status,page,scope=getScope()){const params=new URLSearchParams();if(status)params.set('status',status);if(page>1)params.set('page',page);if(actor?.role==='office'&&actor.can_export_report&&scope==='mine')params.set('scope','mine');history.pushState({},'',location.pathname+(params.size?'?'+params:''));return renderList({preserveShell:true});}
function listFrameMarkup(status,scope){
 const scopeFilter=actor.role==='office'&&actor.can_export_report?`<div class="scope-filter" aria-label="กรองตามผู้เปิดใบ PO"><button data-scope="all" class="${scope==='all'?'selected':''}" aria-pressed="${scope==='all'}">ทุกคน</button><button data-scope="mine" class="${scope==='mine'?'selected':''}" aria-pressed="${scope==='mine'}">ของฉัน</button></div>`:'';
 const filterButtons=`<div class="filters" aria-label="กรองสถานะ">${[['','ทั้งหมด'],...Object.entries(statuses)].map(([s,label])=>`<button data-filter="${s}" class="${status===s?'selected':''}" aria-pressed="${status===s}">${label}</button>`).join('')}</div>`;
 return `<div id="po-metrics" class="metrics" hidden></div><section class="panel"><div id="po-panel-head" class="panel-head" hidden><h2>รายการใบ PO</h2><button data-action="refresh" class="ghost">↻ โหลดล่าสุด</button></div>${scopeFilter}${filterButtons}<div id="po-orders" class="orders" style="margin-top:20px"></div><div id="po-pagination" class="pagination" hidden></div></section>`;
}
function fillListFrame(target,list,stats,status,scope){
 const metrics=document.querySelector('#po-metrics');
 const metricStatuses=['pending','approved','received','closed','rejected'];
 metrics.hidden=false;
 metrics.className='metrics';
 metrics.innerHTML=metricStatuses.map(s=>`<div class="metric"><span class="marker"></span><small>${statuses[s]}</small><strong>${Number(stats[s]||0)} <small>ใบ</small></strong></div>`).join('');
 const panelHead=document.querySelector('#po-panel-head');
 panelHead.hidden=false;
 for(const button of target.querySelectorAll('[data-filter]')){const selected=button.dataset.filter===status;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}
 for(const button of target.querySelectorAll('[data-scope]')){const selected=button.dataset.scope===scope;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));}
 const orders=document.querySelector('#po-orders');
 orders.innerHTML=list.rows.map(p=>`<article class="order"><div><span class="order-id">${esc(p.po_number)}</span><h3>${esc(p.items[0].name)}${p.items.length>1?` <small>และอีก ${p.items.length-1} รายการ</small>`:''}</h3><small>${esc(p.requester_name)} · ${poDate(p.po_date)}</small></div><div class="order-progress">${badge(p.status)}${tracker(p)}</div><div class="order-actions"><div class="amount">฿ ${money(p.total_cents)}</div><button data-detail="${p.id}">ดูรายละเอียด ↗</button></div></article>`).join('')||`<div class="empty"><h2>${status?'ยังไม่มีใบ PO ในสถานะนี้':'ยังไม่มีใบ PO'}</h2><p>${actor.role==='office'?'เริ่มจากเปิดใบ PO และตรวจทานรายการก่อนส่งให้เจ้าของ':'เมื่อออฟฟิศเปิดใบ PO คำขอจะแสดงที่นี่'}</p>${actor.role==='office'?'<button data-go="create" class="primary">＋ เปิดใบ PO</button>':''}</div>`;
 const pagination=document.querySelector('#po-pagination');
 pagination.hidden=list.total===0;
 pagination.innerHTML=list.total?`<span>${(getPage()-1)*10+1}–${Math.min(getPage()*10,list.total)} จาก ${list.total} ใบ</span><div class="row"><button data-page="${getPage()-1}" ${getPage()===1?'disabled':''}>ก่อนหน้า</button><span>หน้า ${getPage()}</span><button data-page="${getPage()+1}" ${getPage()*10>=list.total?'disabled':''}>ถัดไป</button></div>`:'';
}
async function renderList({preserveShell=false}={}){
 route='list';
 const seq=++loadSequence,status=getFilter(),page=getPage(),scope=getScope();
 let target=preserveShell?document.querySelector('#list-content'):null;
 const reused=Boolean(target);
 if(!reused){
  shell(`<div class="page-head"><div><div class="eyebrow">PURCHASE ORDERS</div><h1>ใบขอซื้อ</h1><p class="muted">ติดตามคำขอ ตั้งแต่อนุมัติจนได้รับใบกำกับภาษี</p></div>${actor.role==='office'?'<button class="primary" data-go="create">＋ เปิดใบ PO</button>':''}</div><div id="page-error"></div><div id="list-content" class="loading" role="status">กำลังโหลดใบ PO…</div>`);
  target=document.querySelector('#list-content');
 }else target.setAttribute('aria-busy','true');
 try{
  const [list,stats]=await Promise.all([service.list(status,page,scope),service.stats(scope)]);
  if(seq!==loadSequence||route!=='list')return;
  if(!list.rows.length&&page>1)return setListState(status,Math.max(1,Math.ceil(list.total/10)),scope);
  if(!target.querySelector('#po-orders'))target.innerHTML=listFrameMarkup(status,scope);
  target.className='';target.removeAttribute('role');target.removeAttribute('aria-busy');
  fillListFrame(target,list,stats,status,scope);
  const errorRegion=document.querySelector('#page-error');if(errorRegion)errorRegion.innerHTML='';
 }catch(e){
  if(seq!==loadSequence)return;
  target.removeAttribute('aria-busy');
  if(!reused)target.innerHTML='<button data-action="refresh">ลองโหลดใหม่</button>';
  showError(e);
  if(reused)document.querySelector('#page-error')?.insertAdjacentHTML('beforeend','<button data-action="refresh">ลองโหลดใหม่</button>');
 }
}

function lineForm(i,n){return `<fieldset class="line-entry"><legend>รายการ ${n+1}</legend><div class="field"><label for="department-${n}">แผนก/สาขา <span class="required-mark">*</span></label><input id="department-${n}" list="department-options-${n}" value="${esc(i.department||'')}" placeholder="ค้นหาแผนก/สาขา" autocomplete="off" data-index="${n}" data-key="department" data-department-field><datalist id="department-options-${n}">${currentDepartments.map(d=>`<option value="${esc(d)}">`).join('')}</datalist><span id="department-${n}-error" class="field-error"></span></div><div class="row spread"><span class="form-note">รายละเอียดสินค้า</span>${draft.items.length>1?`<button type="button" class="ghost danger" data-remove="${n}">ลบรายการ ${n+1}</button>`:''}</div>${field('name-'+n,'ชื่อสินค้า *',i.name,'text',`data-index="${n}" data-key="name" maxlength="200"`)}<div class="field"><label for="spec-${n}">รายละเอียด / สเปคสินค้า <span class="required-mark">*</span></label><textarea id="spec-${n}" data-index="${n}" data-key="spec" maxlength="2000">${esc(i.spec)}</textarea><span id="spec-${n}-error" class="field-error"></span></div>${field('source-'+n,'แหล่งซื้อ *',i.source,'text',`data-index="${n}" data-key="source" maxlength="300" placeholder="ชื่อร้าน ผู้ขาย หรือเว็บไซต์"`)}<div class="line-grid quantity-grid">${field('qty-'+n,'จำนวน *',i.qty,'number',`data-index="${n}" data-key="qty" min="0.001" max="1000000" step="0.001" inputmode="decimal"`)}${field('unit-'+n,'หน่วย *',i.unit||'','text',`data-index="${n}" data-key="unit" maxlength="50"`)}${field('unit_price-'+n,'ราคาต่อหน่วย (บาท) *',i.unit_price,'number',`data-index="${n}" data-key="unit_price" min="0.01" step="0.01" inputmode="decimal"`)}<div class="field"><span>ภาษี</span><label class="check"><input type="checkbox" data-index="${n}" data-key="vat" ${i.vat?'checked':''}> VAT 7% <span class="muted">(ไม่ติ๊ก = NON VAT)</span></label></div></div><fieldset class="payment-choice"><legend>การชำระเงิน <span class="required-mark">*</span></legend><div class="payment-options">${Object.entries(paymentLabels).map(([value,label])=>`<label class="payment-option" for="payment-${value}-${n}"><input id="payment-${value}-${n}" type="radio" name="payment-method-${n}" value="${value}" data-index="${n}" data-key="payment_method" aria-describedby="payment-credit-${n}-error" ${i.payment_method===value?'checked':''}> ${esc(label)}</label>`).join('')}</div><span id="payment-credit-${n}-error" class="field-error"></span></fieldset><div class="vat-calc" id="vat-calc-${n}"></div><div class="field"><label for="note-${n}">หมายเหตุ</label><textarea id="note-${n}" data-index="${n}" data-key="note" maxlength="2000" placeholder="รายละเอียดเพิ่มเติม (ถ้ามี)">${esc(i.note)}</textarea><span id="note-${n}-error" class="field-error"></span></div><div class="right muted" id="line-total-${n}"></div></fieldset>`;}
function updateTotals(){let total=0,base=0,tax=0;draft.items.forEach((i,n)=>{try{const line=validateItems([{...i,name:i.name||'สินค้า',spec:i.spec||'รายละเอียด',source:i.source||'แหล่งซื้อ'}])[0];total+=line.total_cents;base+=line.vat?line.base_cents:0;tax+=line.tax_cents;document.querySelector('#line-total-'+n).textContent='รวมรายการนี้ ฿ '+money(line.total_cents);document.querySelector('#vat-calc-'+n).innerHTML=i.vat?`<span>คำนวณอัตโนมัติจากราคารวม VAT</span><strong>ก่อน VAT ฿ ${money(line.base_cents)} · VAT ฿ ${money(line.tax_cents)}</strong>`:'<span>NON VAT</span>';}catch{document.querySelector('#line-total-'+n).textContent='';document.querySelector('#vat-calc-'+n).textContent='';}});document.querySelector('#draft-base').textContent='฿ '+money(base);document.querySelector('#draft-tax').textContent='฿ '+money(tax);document.querySelector('#draft-total').textContent='฿ '+money(total);}
async function renderCreate(){route='create';++loadSequence;if(!draft)draft={po_date:todayBangkok(),department:'',items:[blank()],key:crypto.randomUUID(),dirty:false};let deptList;try{deptList=await departments();}catch(e){shell('<div id="page-error"></div><button data-go="create">ลองโหลดแผนก/สาขาอีกครั้ง</button>');showError(e);return;}if(route!=='create')return;currentDepartments=deptList;shell(`<div class="page-head"><div><div class="eyebrow">NEW PURCHASE ORDER</div><h1>เปิดใบ PO</h1><p class="muted">กรอกรายการ แล้วตรวจทานก่อนส่งอนุมัติ</p></div><button data-go="list">กลับรายการ</button></div><section class="panel"><h2>รายละเอียดใบขอซื้อ</h2><form id="po-form" novalidate><div id="page-error"></div><div class="date-row">${field('po-date','วันที่ใบ PO *',draft.po_date,'date','data-header-key="po_date"')}<div class="field"><span>เวลาบันทึก</span><div class="read-only-value">บันทึกอัตโนมัติเมื่อเปิด PO</div></div></div>${draft.items.map(lineForm).join('')}<button type="button" data-action="add" ${draft.items.length>=50?'disabled':''}>＋ เพิ่มสินค้า</button><div class="summary"><div class="row spread"><span>รวมก่อน VAT</span><strong id="draft-base">฿ 0.00</strong></div><div class="row spread"><span>VAT รวม</span><strong id="draft-tax">฿ 0.00</strong></div><hr><div class="row spread"><strong>ยอดรวมสุทธิ</strong><strong class="grand" id="draft-total">฿ 0.00</strong></div></div><div class="actions"><button type="button" data-go="list">ยกเลิก</button><button type="submit" class="primary">ตรวจทานใบ PO →</button></div></form></section>`);updateTotals();document.querySelector('#po-form').onsubmit=e=>{e.preventDefault();const invalidDepartment=draft.items.findIndex(i=>!deptList.includes(String(i.department||'').trim()));if(invalidDepartment>=0){errorField(document.querySelector('#department-'+invalidDepartment),'เลือกแผนก/สาขาที่มีในระบบ');return;}const invalidPayment=draft.items.findIndex(i=>!Object.hasOwn(paymentLabels,i.payment_method));if(invalidPayment>=0){const input=document.querySelector('#payment-credit-'+invalidPayment);document.querySelectorAll(`[name="payment-method-${invalidPayment}"]`).forEach(radio=>radio.setAttribute('aria-invalid','true'));errorField(input,'เลือกการชำระเงิน เครดิต หรือเงินสด');return;}draft.department=[...new Set(draft.items.map(i=>i.department.trim()))].length===1?draft.items[0].department.trim():'หลายแผนก/สาขา';try{draft.po_date=validatePODate(draft.po_date);draft.validated=validateItems(draft.items);renderReview();}catch(err){showError(err);if(!/^20/.test(draft.po_date)){errorField(document.querySelector('#po-date'),err.message);return;}const n=err.index||0,item= draft.items[n];let key=!item.name.trim()?'name':!item.spec.trim()?'spec':!item.source.trim()?'source':!(Number(item.qty)>0)?'qty':'unit_price';errorField(document.getElementById(key+'-'+n),err.message);}};}
function itemsTable(items){return `<div class="table-wrap" tabindex="0" role="region" aria-label="รายการสินค้า เลื่อนแนวนอนเพื่อดูทั้งหมด"><table><thead><tr><th>สินค้า / สเปค</th><th>แผนก/สาขา</th><th>แหล่งซื้อ</th><th>การชำระเงิน</th><th class="right">จำนวน</th><th class="right">ราคา / หน่วย</th><th>ภาษี</th><th class="right">รวม (บาท)</th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${esc(i.spec)}</small>${i.note?`<small>หมายเหตุ: ${esc(i.note)}</small>`:''}</td><td>${esc(i.department||'-')}</td><td>${esc(i.source)}</td><td>${esc(paymentLabels[i.payment_method]||'ไม่ระบุ')}</td><td class="right">${esc(i.qty)} ${esc(i.unit||'ชิ้น')}</td><td class="right">${money(Math.round(Number(i.unit_price)*100))}</td><td>${i.vat?`VAT 7%<small>ก่อน VAT ${money(i.base_cents)}<br>VAT ${money(i.tax_cents)}</small>`:'NON VAT'}</td><td class="right number">${money(i.total_cents)}</td></tr>`).join('')}</tbody></table></div>`;}
function summary(t,items=[]){return `<div class="summary"><div class="row spread"><span>รวมก่อน VAT <small>(เฉพาะรายการ VAT)</small></span><strong>฿ ${money(vatBase(items))}</strong></div><div class="row spread"><span>VAT รวม</span><strong>฿ ${money(t.tax_cents)}</strong></div><hr><div class="row spread"><strong>ยอดรวมสุทธิ</strong><strong class="grand">฿ ${money(t.total_cents)}</strong></div></div>`;}
function renderReview(){route='review';shell(`<div class="page-head"><div><div class="eyebrow">REVIEW & SUBMIT</div><h1>ตรวจทานก่อนเปิด PO</h1><p class="muted">ตรวจชื่อสินค้า แหล่งซื้อ จำนวน และราคาให้ครบ</p></div></div><section class="panel"><div class="row spread"><h2>สรุปคำขอซื้อ</h2><strong>${poDate(draft.po_date)}</strong></div><p class="form-note"><strong>แผนก/สาขา:</strong> ${esc(draft.department)}</p>${itemsTable(draft.validated)}${summary(totals(draft.validated),draft.validated)}<p class="form-note">เมื่อเปิด PO แล้ว รายการนี้จะส่งให้เจ้าของพิจารณา และไม่สามารถแก้ไขสินค้า / ราคาในใบเดิมได้</p><div id="page-error"></div><div class="actions"><button data-action="edit">← กลับไปแก้ไข</button><button data-action="submit" class="primary">ยืนยันเปิด PO</button></div></section>`);}
async function renderDetail(id){route='detail';const seq=++loadSequence;shell('<div id="page-error"></div><div id="detail-content" class="loading">กำลังโหลดรายละเอียด…</div>');try{const p=await service.detail(id);if(seq!==loadSequence||route!=='detail')return;detail=p;const actions=actor.role==='owner'&&p.status==='pending'?'<button class="danger" data-command="reject">ไม่อนุมัติ</button><button class="primary" data-command="approve">อนุมัติ PO</button>':actor.role==='office'&&p.status==='approved'&&(actor.can_export_report||p.created_by===actor.id)?'<button class="primary" data-command="receive">ได้รับสินค้าครบแล้ว</button>':actor.role==='owner'&&p.status==='received'?'<button class="primary" data-command="close">ตรวจรับใบกำกับภาษีและปิด PO</button>':'';shell(`<div class="page-head"><div><div class="eyebrow">PURCHASE ORDER</div><h1>${esc(p.po_number)}</h1><p class="muted po-meta"><span class="po-meta-date">วันที่ PO ${shortPoDate(p.po_date)} · ${timeOnly(p.created_at)} น.</span><span class="po-meta-requester">เปิดโดย ${esc(p.requester_name)}</span></p></div><button type="button" data-go="list" class="po-back" aria-label="กลับไปหน้ารายการ PO" title="กลับไปหน้ารายการ PO"><span aria-hidden="true">←</span></button></div><div id="page-error"></div><section class="panel"><div class="row spread"><h2>สถานะใบ PO</h2>${badge(p.status)}</div>${tracker(p,true)}${p.status==='rejected'?`<div class="error"><strong>เหตุผลที่ไม่อนุมัติ</strong><br>${esc(p.rejection_reason)}</div>`:''}${p.status==='received'?'<div class="summary">ได้รับสินค้าครบแล้ว · รอออฟฟิศนำใบกำกับภาษีให้เจ้าของ เจ้าของต้องตรวจรับเอกสารก่อนปิด PO</div>':''}${p.status==='closed'?'<div class="summary">✓ เจ้าของยืนยันได้รับใบกำกับภาษีและปิด PO แล้ว</div>':''}${actions?`<div class="actions">${actions}</div>`:''}</section><section class="panel"><h2>รายการสินค้า <small>${p.items.length} รายการ</small></h2>${itemsTable(p.items)}${summary(p,p.items)}</section><section class="panel"><h2>ประวัติการดำเนินการ</h2><ol class="audit">${(p.events||[]).map(e=>`<li><strong>${actionLabels[e.action]||esc(e.action)}</strong> · ${esc(e.actor_name)}<small>${date(e.at)} (เวลาไทย)</small>${e.reason?`<p>${esc(e.reason)}</p>`:''}</li>`).join('')}</ol></section>`);}catch(e){showError(e);const target=document.querySelector('#detail-content');if(target)target.innerHTML='<button type="button" data-go="list" class="po-back" aria-label="กลับไปหน้ารายการ PO" title="กลับไปหน้ารายการ PO">←</button>';}}
function command(action){const p=detail,key=crypto.randomUUID(),title=actionLabels[action];openModal(title,`<p><strong>${esc(p.po_number)}</strong> · ฿ ${money(p.total_cents)}</p><form novalidate><div id="modal-error"></div>${action==='reject'?'<div class="field"><label for="reason">เหตุผลที่ไม่อนุมัติ *</label><textarea id="reason" name="reason" maxlength="2000"></textarea><span class="field-error" id="reason-error"></span></div>':action==='approve'?'<div class="field"><label for="reason">หมายเหตุการอนุมัติ (ถ้ามี)</label><textarea id="reason" name="reason" maxlength="2000"></textarea></div>':`<label class="check"><input type="checkbox" id="ack" name="ack">${action==='close'?'ฉันได้รับใบกำกับภาษีจากออฟฟิศและตรวจสอบแล้ว':'ฉันได้รับสินค้าครบทุกรายการตามใบ PO นี้แล้ว'}</label><span id="ack-error" class="field-error"></span>`}${action==='close'?'<p class="form-note">การปิด PO จะบันทึกผู้ตรวจรับเอกสารและเวลา ไม่สามารถปิดก่อนตรวจรับเอกสารได้</p>':''}<div class="actions"><button type="button" data-cancel autofocus>กลับ</button><button type="submit" class="${action==='reject'?'danger':'primary'}">ยืนยัน${title}</button></div></form>`,async data=>{const reason=String(data.get('reason')||'').trim(),confirmed=data.get('ack')==='on';if(action==='reject'&&!reason){errorField(document.querySelector('#reason'),'กรุณาระบุเหตุผลที่ไม่อนุมัติ');return;}if(['receive','close'].includes(action)&&!confirmed){errorField(document.querySelector('#ack'),'กรุณาติ๊กยืนยันก่อนบันทึก');return;}await withPending(modal.querySelector('[type=submit]'),async()=>{await service.action(p,action,reason,confirmed,key,actor);modal.close();await renderDetail(p.id);notify('บันทึกสำเร็จ: '+title);},document.querySelector('#modal-error'));});}
async function renderReport(month=todayBangkok().slice(0,7)){route='report';const seq=++loadSequence;shell(`<div class="page-head"><div><div class="eyebrow">MONTHLY SUMMARY</div><h1>สรุปรายเดือน</h1><p class="muted">ยอดสั่งซื้อคิดจากใบที่เจ้าของอนุมัติแล้ว</p></div></div><section class="panel"><div class="report-controls">${field('report-month','เลือกเดือน',month,'month')}<button class="report-export" data-action="export" disabled>⇩ Export Excel</button></div><div id="page-error"></div><div id="report-content" class="loading">กำลังคำนวณสรุป…</div></section>`);document.querySelector('#report-month').addEventListener('change',e=>renderReport(e.currentTarget.value||todayBangkok().slice(0,7)));try{const report=await service.report(month);if(seq!==loadSequence||route!=='report')return;activeReport={...report,month};renderReportContent(activeReport);}catch(e){showError(e);document.querySelector('#report-content').innerHTML='<button data-action="retry-report">ลองโหลดใหม่</button>';}}
function renderReportContent(report){const target=document.querySelector('#report-content');target.className='';target.innerHTML=`<div class="metrics report-metrics"><div class="metric"><small>ยอดสั่งซื้อ ${monthLabel(report.month)}</small><strong>฿ ${money(report.total_cents)}</strong></div><div class="metric"><small>อนุมัติแล้ว</small><strong>${report.ordered_count} <small>ใบ</small></strong></div><div class="metric"><small>รออนุมัติ</small><strong>${report.pending_count} <small>ใบ</small></strong></div><div class="metric"><small>ไม่อนุมัติ</small><strong>${report.rejected_count} <small>ใบ</small></strong></div></div><p class="form-note">ยอดรวมเฉพาะสถานะ “รอรับสินค้า”, “รอใบกำกับภาษี” และ “ปิดใบ PO แล้ว” ไม่นับใบที่รออนุมัติหรือไม่อนุมัติ</p><div class="table-wrap"><table><thead><tr><th>เลข PO</th><th>วันที่</th><th>สถานะ</th><th>รายการ</th><th class="right">ยอดรวม</th></tr></thead><tbody>${report.rows.map(p=>`<tr><td>${esc(p.po_number)}</td><td>${poDate(p.po_date)}</td><td>${statuses[p.status]}</td><td>${p.items.length}</td><td class="right">฿ ${money(p.total_cents)}</td></tr>`).join('')||'<tr><td colspan="5">ยังไม่มีใบ PO ในเดือนนี้</td></tr>'}</tbody></table></div>`;document.querySelector('[data-action="export"]').disabled=false;}
async function renderUsers(){route='users';const seq=++loadSequence;shell(`<div class="page-head"><div><div class="eyebrow">ACCESS MANAGEMENT</div><h1>ผู้ใช้งาน</h1><p class="muted">เจ้าของกำหนดบัญชีและรหัสผ่านให้ออฟฟิศ</p></div></div><div class="split"><section class="panel"><h2>บัญชีออฟฟิศ</h2><div id="user-list" class="loading">กำลังโหลดผู้ใช้งาน…</div></section><section class="panel"><h2>เพิ่มหรือเปลี่ยนรหัสผ่าน</h2><form id="user-form" novalidate><div id="page-error"></div>${field('account-id','ชื่อผู้ใช้','','text','autocomplete="off" placeholder="ชื่อบัญชีที่เจ้าของกำหนด" maxlength="50"')}${field('display-name','ชื่อที่แสดง','','text','maxlength="100" placeholder="น้องฝ้าย"')}${passwordControl('new-password','รหัสผ่านตัวเลข 6 หลัก','new-password')}<p class="form-note">กรอกบัญชีเดิมเพื่อเปลี่ยนรหัสผ่าน หรือกรอกบัญชีใหม่เพื่อเพิ่มผู้ใช้</p><button type="submit" class="primary">บันทึกบัญชีออฟฟิศ</button></form></section></div>`);bindPasswordToggles();const officePassword=document.querySelector('#new-password');officePassword.inputMode='numeric';officePassword.maxLength=6;officePassword.pattern='[0-9]{6}';document.querySelector('#user-form').onsubmit=async e=>{e.preventDefault();const id=document.querySelector('#account-id'),display=document.querySelector('#display-name'),pass=document.querySelector('#new-password');if(!/^[a-zA-Z0-9._]{4,50}$/.test(id.value.trim())){errorField(id,'ใช้ตัวอังกฤษ ตัวเลข จุด หรือขีดล่าง 4–50 ตัว เช่น ชื่อบัญชีที่เจ้าของกำหนด');return;}if(!display.value.trim()){errorField(display,'กรอกชื่อที่แสดง');return;}if(!/^\d{6}$/.test(pass.value)&&pass.value!=='__KEEP__'){errorField(pass,'รหัสผ่านต้องเป็นตัวเลข 6 หลัก');return;}await withPending(e.submitter,async()=>{const account={username:id.value.trim().toLowerCase(),display_name:display.value.trim(),password:pass.value};if(configured)await service.saveOffice(account);else await service.saveOffice(account,actor);editingUser=null;id.value='';display.value='';pass.value='';id.readOnly=false;document.querySelector('[data-user-cancel]')?.remove();await loadUsers(seq);notify('บันทึกบัญชีออฟฟิศแล้ว');id.focus();});};await loadUsers(seq);}
async function loadUsers(seq=loadSequence){try{const users=configured?await service.users():await service.users(actor);userRecords=users;if(seq!==loadSequence||route!=='users')return;document.querySelector('#user-list').className='';document.querySelector('#user-list').innerHTML=users.length?users.map((u,index)=>`<div class="user-row"><span class="avatar" aria-hidden="true">♙</span><div class="user-identity"><strong>${esc(u.display_name)}</strong><small>${esc(u.login_name||u.username||u.login_email)}</small></div><div class="user-actions"><button type="button" class="ghost" data-user-edit="${index}">แก้ไข</button><button type="button" class="ghost danger" data-user-delete="${index}">ลบบัญชี</button></div></div>`).join(''):'<div class="empty">ยังไม่มีบัญชีออฟฟิศ</div>';}catch(e){showError(e);document.querySelector('#user-list').textContent='โหลดผู้ใช้งานไม่ได้';}}
function setup(){route='setup';++loadSequence;shell(`<div class="page-head"><div><div class="eyebrow">CONNECTION</div><h1>การเชื่อมต่อ</h1><p class="muted">เว็บ PO และฐานข้อมูลแยกอิสระจากระบบอื่น</p></div></div><section class="panel"><h2>${configured?'เชื่อมต่อ Supabase ตามการตั้งค่าแล้ว':'ยังไม่ได้เชื่อมต่อ Supabase'}</h2><p>${configured?'บัญชีและใบ PO ใช้ข้อมูลจากโปรเจกต์ Supabase ที่ตั้งค่าไว้':'ขณะนี้ใช้ระบบทดลอง เจ้าของตั้งรหัสผ่านแรกเข้าและกำหนดบัญชีออฟฟิศได้ ข้อมูล PO จะไม่ถูกส่งไปฐานข้อมูล'}</p><ol><li>สร้าง Supabase project ใหม่สำหรับ PO The Grands</li><li>รัน <code>supabase/001_schema.sql</code> และ deploy <code>supabase/functions/manage-user</code></li><li>สร้างบัญชีเจ้าของครั้งแรกผ่าน Dashboard</li><li>ใส่ Project URL และ publishable key ใน <code>dist/config.js</code></li><li>เข้าสู่ระบบเป็นเจ้าของแล้วกำหนดบัญชีออฟฟิศจากเมนู “ผู้ใช้งาน”</li></ol><p class="form-note">ดูขั้นตอนทั้งหมดใน SUPABASE-SETUP.md</p><button data-go="list" class="primary">กลับไปใบขอซื้อ</button></section>`);}
async function renderDepartments(){route='departments';try{const list=await departments();shell(`<div class="page-head"><div><div class="eyebrow">WORKSPACE SETTINGS</div><h1>แผนก/สาขา</h1><p class="muted">จัดการรายการที่แสดงในช่องเลือกตอนเปิดใบ PO</p></div></div><section class="panel"><div class="panel-head"><h2>รายการแผนก/สาขา</h2><span class="form-note">${list.length} รายการ</span></div><div id="page-error"></div><form id="department-form" class="row"><input id="department-name" placeholder="ชื่อแผนกหรือสาขาใหม่" maxlength="100" required><button class="primary">เพิ่มรายการ</button></form><div class="department-manager">${list.map((d,i)=>`<div class="row spread department-row"><span>${esc(d)}</span><button type="button" class="ghost danger department-archive" data-department-delete="${i}" aria-label="เก็บ ${esc(d)} เข้าคลัง" title="เก็บเข้าคลัง"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M9 3h6l1 2h4v2H4V5h4l1-2Zm-2 6h10l-.7 12H7.7L7 9Z"/><path d="M10 11v7m4-7v7" fill="none" stroke="white" stroke-width="1.8" stroke-linecap="round"/></svg></button></div>`).join('')}</div></section>`);document.querySelector('#department-form').onsubmit=async e=>{e.preventDefault();const input=document.querySelector('#department-name'),name=input.value.trim();if(!name)return;if(list.includes(name)){notify('มีรายการนี้แล้ว');return;}await withPending(e.submitter,async()=>{if(configured)await service.addDepartment(name);else localStorage.setItem('po-the-grands-demo-departments-v1',JSON.stringify([...list,name]));await renderDepartments();notify('เพิ่มแผนก/สาขาแล้ว');});};}catch(e){showError(e);}}
async function go(next){if(pending)return;const navigate=()=>{if(next==='list')return renderList();if(next==='create'&&actor.role==='office')return renderCreate();if(next==='report'&&actor.role==='office')return renderReport();if(next==='departments'&&actor.role==='office')return renderDepartments();if(next==='users'&&actor.role==='owner')return renderUsers();if(next==='setup')return setup();};if(draft?.dirty&&['create','review'].includes(route)&&!['create','review'].includes(next)){openModal('ออกจากใบ PO ที่ยังไม่ส่ง?',`<p>รายการที่กรอกยังไม่ถูกบันทึก ออกจากหน้านี้จะล้างข้อมูลร่าง</p><div class="actions"><button data-cancel autofocus>กรอกต่อ</button><button id="discard" class="danger">ทิ้งร่างและออก</button></div>`);document.querySelector('#discard').onclick=()=>{draft=null;modal.close();navigate();};}else navigate();}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.headerKey&&draft){draft[el.dataset.headerKey]=el.value;draft.dirty=true;draft.key=crypto.randomUUID();}if(el.dataset.key&&draft){if(el.type==='radio'&&!el.checked)return;draft.items[Number(el.dataset.index)][el.dataset.key]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.key==='payment_method'){document.querySelectorAll(`[name="${el.name}"]`).forEach(radio=>radio.removeAttribute('aria-invalid'));const paymentError=document.getElementById('payment-credit-'+el.dataset.index+'-error');if(paymentError)paymentError.textContent='';}draft.dirty=true;draft.key=crypto.randomUUID();el.removeAttribute('aria-invalid');const err=document.getElementById(el.id+'-error');if(err)err.textContent='';if(el.tagName==='TEXTAREA'){el.style.height='auto';el.style.height=Math.max(100,el.scrollHeight)+'px';}updateTotals();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="reset-owner"],[data-action="back-login"]');if(!b)return;if(b.dataset.action==='reset-owner'&&!configured)resetOwner();if(b.dataset.action==='back-login')login();});
document.addEventListener('submit',e=>{if(!configured&&route==='users'&&editingUser){const pass=document.querySelector('#new-password');if(pass&&!pass.value)pass.value='__KEEP__';}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-user-edit]');if(!b||route!=='users')return;const user=userRecords[Number(b.dataset.userEdit)],id=document.querySelector('#account-id'),display=document.querySelector('#display-name'),pass=document.querySelector('#new-password');if(!user||!id||!display||!pass)return;editingUser=user;id.value=user.login_name||user.username||user.login_email;display.value=user.display_name;pass.value='';id.readOnly=false;id.removeAttribute('aria-readonly');let cancel=document.querySelector('[data-user-cancel]');if(!cancel){cancel=document.createElement('button');cancel.type='button';cancel.dataset.userCancel='';cancel.textContent='ยกเลิกแก้ไข';cancel.onclick=()=>{editingUser=null;id.value='';display.value='';pass.value='';id.readOnly=false;cancel.remove();const title=document.querySelector('#user-form-title');if(title)title.textContent='เพิ่มหรือเปลี่ยนรหัสผ่าน';};document.querySelector('#user-form').insertBefore(cancel,document.querySelector('#user-form button[type="submit"]'));}const title=document.querySelector('#user-form-title');if(title)title.textContent='แก้ไขบัญชีออฟฟิศ';display.focus();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||pending)return;if(b.dataset.go)return go(b.dataset.go);if('scope' in b.dataset)return setListState(getFilter(),1,b.dataset.scope);if('filter' in b.dataset)return setListState(b.dataset.filter,1);if(b.dataset.page)return setListState(getFilter(),Number(b.dataset.page));if(b.dataset.detail)return renderDetail(b.dataset.detail);if(b.dataset.command)return command(b.dataset.command);if('departmentDelete' in b.dataset){const list=await departments(),index=Number(b.dataset.departmentDelete),name=list[index];if(name){openModal('เก็บแผนก/สาขาเข้าคลัง?',`<p><strong>${esc(name)}</strong> จะไม่แสดงให้เลือกในใบ PO ใหม่ ประวัติใบเดิมยังอยู่</p><div id="modal-error"></div><div class="actions"><button data-cancel autofocus>กลับ</button><button id="archive-department" class="danger">เก็บเข้าคลัง</button></div>`);document.querySelector('#archive-department').onclick=async()=>{await withPending(document.querySelector('#archive-department'),async()=>{if(configured)await service.archiveDepartment(name);else localStorage.setItem('po-the-grands-demo-departments-v1',JSON.stringify(list.filter((_,i)=>i!==index)));modal.close();await renderDepartments();notify('เก็บแผนก/สาขาเข้าคลังแล้ว');},document.querySelector('#modal-error'));};}return;}if('remove' in b.dataset){draft.items.splice(Number(b.dataset.remove),1);draft.dirty=true;draft.key=crypto.randomUUID();renderCreate();return;}if(b.dataset.reveal)return;switch(b.dataset.action){case 'add':draft.items.push(blank());draft.dirty=true;draft.key=crypto.randomUUID();await renderCreate();document.querySelector('#name-'+(draft.items.length-1))?.focus();break;case 'edit':renderCreate();break;case 'refresh':renderList({preserveShell:true});break;case 'submit':await withPending(b,async()=>{if(configured)await service.create(draft.validated,draft.po_date,draft.key,draft.department);else await service.create(draft.validated,draft.po_date,draft.key,actor,draft.department);draft=null;await setListState('',1);notify('เปิดใบ PO แล้ว รอเจ้าของอนุมัติ');});break;case 'retry-report':renderReport(document.querySelector('#report-month')?.value||activeReport?.month||todayBangkok().slice(0,7));break;case 'export':await withPending(b,async()=>{await exportMonthlyExcel(activeReport,activeReport.month);notify('สร้างไฟล์ Excel แล้ว');});break;case 'logout':openModal('เปลี่ยนบัญชีผู้ใช้งาน?',`<p>ระบบจะออกจากบัญชี ${esc(actor.display_name)} แล้วกลับไปหน้าเข้าสู่ระบบ</p><div class="actions"><button data-cancel autofocus>กลับ</button><button id="logout-confirm" class="primary">ออกจากระบบ</button></div>`);document.querySelector('#logout-confirm').onclick=async()=>{try{if(configured)await api.logout();}finally{draft=null;actor=null;modal.close();login();}};break;case 'reauth':if(modal.open)modal.close();login(true);break;}});
window.addEventListener('beforeunload',e=>{if(draft?.dirty||ownerAccountDirty()){e.preventDefault();e.returnValue='';}});
window.addEventListener('popstate',()=>{if(actor&&route==='list')renderList();});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_visible_purchase_orders',title:'อ่านใบ PO หน้าที่แสดง',description:'Read the current purchase-order page with the same account permissions. Does not change records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('ไม่รับพารามิเตอร์');if(!actor)throw Error('กรุณาเข้าสู่ระบบ');return service.list(getFilter(),getPage(),getScope());}})).catch(()=>{});}catch{}}
const baseShell=shell;
shell=function(body){baseShell(body);document.querySelector('.demo-banner')?.remove();const root=document.querySelector('.shell'),sidebar=document.querySelector('.sidebar>div:first-child'),identity=document.querySelector('.identity'),topbar=document.querySelector('.topbar');root?.classList.add(`role-${actor.role}`);if(identity&&sidebar){identity.classList.add('sidebar-identity');sidebar.append(identity);}topbar?.insertAdjacentHTML('beforeend',notificationButton());const departmentNav=document.querySelector('[data-go="departments"]');if(departmentNav)departmentNav.innerHTML='<svg class="nav-pin" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-6-6.2-6-11a6 6 0 1 1 12 0c0 4.8-6 11-6 11Z"/><circle cx="12" cy="10" r="2"/></svg><span>แผนก/สาขา</span>';if(actor.role==='office'&&!actor.can_export_report){document.querySelector('[data-go="report"]')?.remove();document.querySelector('[data-go="departments"]')?.remove();}if(actor.role==='owner'&&route==='list')document.querySelector('.page-head')?.remove();refreshNotifications();};
const saveOfficeWithPermission=service.saveOffice.bind(service);
service.saveOffice=(account,...args)=>saveOfficeWithPermission({...account,can_export_report:document.querySelector('#can-export-report')?.checked===true},...args);
const baseRenderUsers=renderUsers;
renderUsers=async function(){await baseRenderUsers();const form=document.querySelector('#user-form'),pass=document.querySelector('#new-password'),display=document.querySelector('#display-name');if(!form||!pass||!display)return;display.closest('.field')?.replaceWith(Object.assign(document.createElement('input'),{type:'hidden',id:'display-name'}));pass.removeAttribute('maxlength');pass.removeAttribute('pattern');pass.inputMode='text';pass.minLength=6;pass.closest('.field')?.querySelector('label')?.replaceChildren('รหัสผ่านอย่างน้อย 6 ตัวอักษร');form.querySelector('.form-note')?.insertAdjacentHTML('beforebegin','<label class="permission-check"><input type="checkbox" id="can-export-report"> <span><strong>ตั้งเป็นบัญชีหลัก</strong><small>จัดการแผนก/สาขา และดูหรือ Export รายงานรวม</small></span></label>');form.onsubmit=async e=>{e.preventDefault();const id=document.querySelector('#account-id'),password=document.querySelector('#new-password');if(!/^[a-zA-Z0-9._]{4,50}$/.test(id.value.trim())){errorField(id,'ใช้ตัวอังกฤษ ตัวเลข จุด หรือขีดล่าง 4–50 ตัว เช่น ชื่อบัญชีที่เจ้าของกำหนด');return;}if(password.value&&password.value!=='__KEEP__'&&password.value.length<6){errorField(password,'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร');return;}if(!editingUser&&password.value.length<6){errorField(password,'บัญชีใหม่ต้องใช้รหัสผ่านอย่างน้อย 6 ตัวอักษร');return;}await withPending(e.submitter,async()=>{const username=id.value.trim().toLowerCase(),account={username,display_name:username,password:password.value||'__KEEP__'};if(configured)await service.saveOffice(account);else await service.saveOffice(account,actor);editingUser=null;await renderUsers();notify('บันทึกบัญชีออฟฟิศแล้ว');document.querySelector('#account-id')?.focus();});};userRecords.forEach((user,index)=>{const row=document.querySelectorAll('.user-row')[index];if(!row)return;const username=user.login_name||user.username||user.login_email;row.querySelector('div>strong')?.replaceChildren(username);row.querySelector('div>small:not(.password-hint)')?.remove();if(user.can_export_report===true||user.username==='ชื่อบัญชีที่เจ้าของกำหนด'||user.login_name==='ชื่อบัญชีที่เจ้าของกำหนด')row.querySelector('.user-identity')?.insertAdjacentHTML('beforeend','<span class="permission-badge">บัญชีหลัก</span>');});};
function ownerAccountDirty(){return route==='account'&&([...document.querySelectorAll('.route-account .password-wrap input')].some(input=>input.value)||document.querySelector('#owner-login-name')?.value.trim()!==(actor?.login_name||''));}
function renderOwnerAccount(){
 if(!configured||actor?.role!=='owner')return;
 route='account';
 shell(`<div class="page-head"><div><h1>บัญชีของฉัน</h1><p class="muted">เปลี่ยนชื่อเข้าระบบหรือรหัสผ่านของบัญชีเจ้าของ</p></div></div><section class="panel"><h2>ชื่อสำหรับเข้าสู่ระบบ</h2><p class="muted">ชื่อเข้าระบบปัจจุบัน: <strong>${esc(actor.login_name||actor.login_email)}</strong></p><p class="form-note">อีเมลบัญชี: ${esc(actor.login_email)} · อีเมลเดิมยังใช้เข้าสู่ระบบได้</p><form id="owner-name-form" novalidate><div id="owner-name-error"></div>${field('owner-login-name','ชื่อสำหรับเข้าสู่ระบบ',actor.login_name||'','text','autocomplete="username" maxlength="50" placeholder="เช่น Nitwadee"')}<p class="form-note">ใช้ตัวอังกฤษ ตัวเลข จุด หรือขีดล่าง 4–50 ตัว ไม่แยกตัวพิมพ์เล็กและใหญ่</p>${passwordControl('owner-name-password','รหัสผ่านปัจจุบัน')}<button type="submit" class="primary">บันทึกชื่อเข้าระบบ</button></form></section><section class="panel"><h2>เปลี่ยนรหัสผ่าน</h2><form id="owner-password-form" novalidate><div id="owner-password-error"></div>${passwordControl('owner-current-password','รหัสผ่านปัจจุบัน')}${passwordControl('owner-new-password','รหัสผ่านใหม่','new-password')}${passwordControl('owner-confirm-password','ยืนยันรหัสผ่านใหม่','new-password')}<p class="form-note">รหัสผ่านใหม่ต้องมีอย่างน้อย 6 ตัวอักษร</p><button type="submit" class="primary">บันทึกรหัสผ่านใหม่</button></form></section>`);
 bindPasswordToggles();
 document.querySelector('#owner-name-form').onsubmit=async e=>{
  e.preventDefault();const name=document.querySelector('#owner-login-name'),password=document.querySelector('#owner-name-password');
  if(!/^[a-zA-Z0-9._]{4,50}$/.test(name.value.trim()))return errorField(name,'ใช้ตัวอังกฤษ ตัวเลข จุด หรือขีดล่าง 4–50 ตัว');
  if(!password.value)return errorField(password,'กรอกรหัสผ่านปัจจุบันเพื่อยืนยัน');
  await withPending(e.submitter,async()=>{const user=await service.updateOwnerLoginName({username:name.value.trim(),currentPassword:password.value});Object.assign(actor,user);name.value=actor.login_name||'';document.querySelector('.route-account .panel .muted strong')?.replaceChildren(actor.login_name||actor.login_email);password.value='';document.querySelector('#owner-name-error').replaceChildren();document.querySelector('.sidebar-identity strong')?.replaceChildren(actor.display_name);notify('บันทึกชื่อเข้าระบบแล้ว');},document.querySelector('#owner-name-error'));
 };
 document.querySelector('#owner-password-form').onsubmit=async e=>{
  e.preventDefault();const current=document.querySelector('#owner-current-password'),password=document.querySelector('#owner-new-password'),confirm=document.querySelector('#owner-confirm-password');
  if(!current.value)return errorField(current,'กรอกรหัสผ่านปัจจุบันเพื่อยืนยัน');
  if(password.value.length<6)return errorField(password,'รหัสผ่านใหม่ต้องมีอย่างน้อย 6 ตัวอักษร');
  if(password.value!==confirm.value)return errorField(confirm,'รหัสผ่านทั้งสองช่องไม่ตรงกัน');
  await withPending(e.submitter,async()=>{await service.changeOwnerPassword({currentPassword:current.value,newPassword:password.value});current.value='';password.value='';confirm.value='';document.querySelector('#owner-password-error').replaceChildren();actor=null;login();notify('บันทึกรหัสผ่านใหม่แล้ว กรุณาเข้าสู่ระบบด้วยรหัสใหม่');},document.querySelector('#owner-password-error'));
 };
}
const baseGo=go;
go=function(next){if(pending)return;if(route==='account'&&next!==route&&ownerAccountDirty()){openModal('ออกจากบัญชีที่ยังไม่บันทึก?',`<p>ชื่อหรือรหัสผ่านที่กรอกยังไม่ถูกบันทึก ออกจากหน้านี้จะล้างข้อมูลที่กรอก</p><div class="actions"><button data-cancel autofocus>กรอกต่อ</button><button id="discard-account" class="danger">ทิ้งข้อมูลและออก</button></div>`);document.querySelector('#discard-account').onclick=()=>{document.querySelectorAll('.route-account input').forEach(input=>input.value='');route='account-discarded';modal.close();go(next);};return;}if(next==='account'&&configured&&actor?.role==='owner'){const url=new URL(location.href);url.searchParams.set('view','account');history.replaceState({},'',url);return renderOwnerAccount();}const url=new URL(location.href);url.searchParams.delete('view');history.replaceState({},'',url);if(next==='report'&&actor?.role==='office'&&!actor.can_export_report){notify('บัญชีนี้ไม่มีสิทธิ์ดูรายงานรวม');return;}return baseGo(next);};
if(recoveryCallback)beginOwnerRecovery();else if(!configured&&demoAuth.needsSetup())renderOwnerSetup();else if(configured){app.innerHTML='<main class="login"><section class="panel" role="status">กำลังตรวจสอบ session…</section></main>';api.restoreSession().then(restored=>{if(restored){actor=restored;if(new URLSearchParams(location.search).get('view')==='account'&&actor.role==='owner')renderOwnerAccount();else renderList();}else login();}).catch(error=>{login();showError(error);});}else login();
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="notifications"],[data-notification-po]');if(!button)return;if(button.dataset.action==='notifications')openNotifications();if(button.dataset.notificationPo){modal.close();renderDetail(button.dataset.notificationPo);}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-user-edit]');if(!button)return;queueMicrotask(()=>{const user=userRecords[Number(button.dataset.userEdit)],permission=document.querySelector('#can-export-report');if(permission&&user)permission.checked=user.can_export_report===true||user.username==='ชื่อบัญชีที่เจ้าของกำหนด';});});
document.addEventListener('input',e=>{const input=e.target;if(!input.matches?.('input,textarea,select')||input.getAttribute('aria-invalid')!=='true')return;input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');const error=document.getElementById(input.id+'-error');if(error)error.textContent='';});
document.addEventListener('submit',e=>{if(e.target.id!=='po-form')return;const department=[...document.querySelectorAll('[data-department-field]')].find(input=>!input.value.trim()),missingUnit=[...document.querySelectorAll('[data-key="unit"]')].find(input=>!input.value.trim()),invalid=department&&!department.value.trim()?department:missingUnit;if(!invalid)return;e.preventDefault();e.stopImmediatePropagation();errorField(invalid,invalid===department?'เลือกแผนก/สาขา':'กรอกหน่วย เช่น กล่อง แพ็ก ชิ้น หรือกิโลกรัม');},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-user-delete]');if(!b||route!=='users')return;const user=userRecords[Number(b.dataset.userDelete)];if(!user)return;openModal('ลบบัญชีออฟฟิศ?',`<p>บัญชี <strong>${esc(user.display_name)}</strong> (${esc(user.login_name||user.username||user.login_email)}) จะเข้าสู่ระบบไม่ได้อีกต่อไป แต่ใบ PO และประวัติการดำเนินการจะยังคงอยู่</p><div class="actions"><button data-cancel autofocus>ยกเลิก</button><button id="delete-user-confirm" class="danger">ลบบัญชี</button></div>`);document.querySelector('#delete-user-confirm').onclick=async()=>{await withPending(document.querySelector('#delete-user-confirm'),async()=>{if(configured)await service.deleteUser(user);else await service.deleteUser(actor,user);modal.close();await loadUsers();notify('ลบบัญชีแล้ว');});};});
if(!configured)service.deleteUser=(actor,user)=>demoAuth.deleteUser(actor,user);

document.addEventListener('click',e=>{const button=e.target.closest('[data-action="owner-recovery-request"],[data-action="owner-recovery-cancel"]');if(!button||button.disabled||pending)return;if(button.dataset.action==='owner-recovery-request')requestOwnerRecovery();else{api.cancelOwnerRecovery();login();}});

document.addEventListener('keydown',navigatePOForm);
